export const STORAGE='posle-urokov:v1';
export const categories={sport:'Спорт',tutor:'Репетитор',club:'Кружок',school:'Учёба',other:'Личное'};
export function dateKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
export function parseDate(s){return new Date(`${s}T12:00:00`);}
export function addDays(s,n){const d=parseDate(s);d.setDate(d.getDate()+n);return dateKey(d);}
export function weekStart(s){const d=parseDate(s);return addDays(s,-((d.getDay()+6)%7));}
export const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&s>='2000-01-01'&&s<='2100-12-31'&&dateKey(parseDate(s))===s;
export const validTime=s=>typeof s==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(s);
export const minutes=s=>Number(s.slice(0,2))*60+Number(s.slice(3));
export function emptyData(){return {version:1,tasks:[],activities:[],completed:[],settings:{reminders:false}};}
const txt=(v,n)=>typeof v==='string'&&v.length<=n;
export function validateData(d){
 if(!d||d.version!==1||!Array.isArray(d.tasks)||!Array.isArray(d.activities)||!Array.isArray(d.completed)||!d.settings||typeof d.settings.reminders!=='boolean')throw Error('Файл не похож на резервную копию «После уроков».');
 if(d.tasks.length>3000||d.activities.length>500||d.completed.length>20000)throw Error('В файле слишком много записей.');
 const ids=new Set();
 for(const x of [...d.tasks,...d.activities]){if(!x||!txt(x.id,100)||!/^[a-zA-Z0-9_-]{1,100}$/.test(x.id)||ids.has(x.id)||!txt(x.title,120)||!x.title.trim()||!validDate(x.date)||!Object.hasOwn(categories,x.category)||!txt(x.notes,2000))throw Error('Проверьте названия, даты и категории записей.');ids.add(x.id);}
 for(const t of d.tasks)if(typeof t.done!=='boolean'||(t.time!==''&&!validTime(t.time))||!Number.isInteger(t.duration)||t.duration<5||t.duration>480)throw Error('Некорректные данные дела.');
 for(const a of d.activities)if(!validTime(a.time)||!validTime(a.end)||a.end<=a.time||!['none','weekly'].includes(a.repeat)||!txt(a.location,160))throw Error('Некорректные данные занятия.');
 if(d.completed.some(x=>typeof x!=='string'||x.length>120))throw Error('Некорректные отметки занятий.');
 // Copy only known fields. Imported files cannot alter arbitrary application state.
 return {version:1,tasks:d.tasks.map(({id,title,date,time,duration,category,notes,done})=>({id,title,date,time,duration,category,notes,done})),activities:d.activities.map(({id,title,date,time,end,repeat,category,notes,location})=>({id,title,date,time,end,repeat,category,notes,location})),completed:[...new Set(d.completed)],settings:{reminders:d.settings.reminders}};
}
export function occurrences(data,date){return data.activities.filter(a=>a.date===date||(a.repeat==='weekly'&&a.date<=date&&parseDate(a.date).getDay()===parseDate(date).getDay())).map(a=>({...a,occurrenceDate:date,done:data.completed.includes(`${a.id}@${date}`)})).sort((a,b)=>a.time.localeCompare(b.time));}
export function conflicts(data,item){return data.activities.filter(a=>{if(a.id===item.id)return false;const sameDay=parseDate(a.date).getDay()===parseDate(item.date).getDay();const meets=a.date===item.date||(sameDay&&((a.repeat==='weekly'&&a.date<=item.date)||(item.repeat==='weekly'&&item.date<=a.date)));return meets&&minutes(item.time)<minutes(a.end)&&minutes(item.end)>minutes(a.time);});}
export function dueReminders(data,now){const today=dateKey(now);return [...data.tasks.filter(t=>!t.done&&t.date===today&&t.time).map(t=>({...t,key:`t:${t.id}:${t.date}:${t.time}`})),...occurrences(data,today).filter(a=>!a.done).map(a=>({...a,key:`a:${a.id}:${today}:${a.time}`}))].filter(x=>{const delta=new Date(`${today}T${x.time}:00`)-now;return delta>=0&&delta<=15*60000;});}
export function demoData(today){const d=emptyData();d.activities=[{id:'demo-basket',title:'Баскетбол',date:today,time:'16:00',end:'17:30',repeat:'weekly',category:'sport',location:'Спортзал школы',notes:'Форма, кроссовки и бутылка воды'},{id:'demo-english',title:'Английский с репетитором',date:addDays(today,1),time:'17:00',end:'18:00',repeat:'weekly',category:'tutor',location:'Онлайн',notes:'Повторить слова к уроку'},{id:'demo-theatre',title:'Театральная студия',date:addDays(today,2),time:'15:30',end:'17:00',repeat:'weekly',category:'club',location:'Кабинет 204',notes:'Взять текст роли'}];d.tasks=[{id:'demo-maths',title:'Решить задачи по алгебре',date:today,time:'14:30',duration:40,category:'school',done:false,notes:'Страница 48, № 125 и 126'},{id:'demo-words',title:'Выучить слова по английскому',date:today,time:'19:00',duration:20,category:'tutor',done:false,notes:'Unit 3, первые 15 слов'},{id:'demo-bag',title:'Собрать сумку на тренировку',date:today,time:'15:30',duration:10,category:'sport',done:true,notes:''}];return d;}
function escICS(s){return s.replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;').replaceAll('\r','');}
export function calendarExport(data){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Posle Urokov//Planner RU//RU','CALSCALE:GREGORIAN'];const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');for(const a of data.activities){lines.push('BEGIN:VEVENT',`UID:${a.id}@posle-urokov`,`DTSTAMP:${stamp}`,`DTSTART:${a.date.replaceAll('-','')}T${a.time.replace(':','')}00`,`DTEND:${a.date.replaceAll('-','')}T${a.end.replace(':','')}00`,`SUMMARY:${escICS(a.title)}`,`LOCATION:${escICS(a.location)}`,`DESCRIPTION:${escICS(a.notes)}`,...(a.repeat==='weekly'?['RRULE:FREQ=WEEKLY']:[]),'END:VEVENT');}for(const t of data.tasks.filter(t=>!t.done)){lines.push('BEGIN:VTODO',`UID:${t.id}@posle-urokov`,`DTSTAMP:${stamp}`,`SUMMARY:${escICS(t.title)}`,`DUE;VALUE=DATE:${t.date.replaceAll('-','')}`,`DESCRIPTION:${escICS(t.notes)}`,'END:VTODO');}lines.push('END:VCALENDAR');return lines.join('\r\n')+'\r\n';}
